<script setup>
import {ref,computed,onMounted} from 'vue'
import CountrySelect from '../shared/CountrySelect.vue'
import LanguageSelect from '../commerce/LanguageSelect.vue'
import EducationLevelSelect from '../commerce/EducationLevelSelect.vue'
import {call} from '../service'
import {editableSocials} from '../commerce/socials.js'
const props=defineProps({member:Object}),emit=defineEmits(['completed'])
const step=ref(0),loading=ref(true),busy=ref(false),error=ref(''),existing=ref(false),phoneVerified=ref(false)
const form=ref({display_name:'',username:'',country:'Sri Lanka',kind:props.member.role==='Admin'?'Institute':'Teacher',languages:'',grades:'',curriculum:'',bio:'',tagline:'',qualifications:'',socials:{},is_school:false})
const steps=['Basic details','Teaching details','Review & save']
const valid=computed(()=>!!form.value.display_name?.trim()&&!!form.value.country&&/^[a-z][a-z0-9_]{2,29}$/.test(form.value.username||''))
async function load(){loading.value=true;error.value='';try{const r=await call('me',{},'profiles');phoneVerified.value=!!r.phone_verified;if(r.profile){Object.assign(form.value,r.profile);form.value.is_school=!!r.profile.is_school;form.value.socials=editableSocials(r.profile.socials);existing.value=true}else form.value.display_name=props.member.full_name||''}catch(e){error.value=e.message}finally{loading.value=false}}
function next(){if(valid.value&&!busy.value)step.value=Math.min(2,step.value+1)}
async function save(){if(step.value!==2||!valid.value||!phoneVerified.value||busy.value)return;busy.value=true;error.value='';try{await call('save_profile',{data:form.value},'profiles');emit('completed')}catch(e){error.value=e.message}finally{busy.value=false}}
onMounted(load)
</script>
<template><section class="setup-profile">
<p v-if="loading" role="status">Loading your saved details…</p>
<template v-else><ol class="setup-steps" aria-label="Profile setup progress"><li v-for="(title,index) in steps" :key="title" :aria-current="step===index?'step':undefined" :class="{current:step===index,done:step>index}"><span>{{index+1}}</span>{{title}}</li></ol>
<form @submit.prevent="step===2?save():next()">
<section v-if="step===0"><h2>Start with the basics</h2><p>Your signup details are filled in where available. Required fields are marked below.</p><label>{{form.kind==='Institute'?'Institute name':'Display name'}} · Required<input v-model="form.display_name" required maxlength="120" autocomplete="name"></label><label>Username · Required<input v-model.trim="form.username" :readonly="existing" required pattern="[a-z][a-z0-9_]{2,29}" maxlength="30" autocapitalize="none" spellcheck="false"></label><small>{{existing?'Your username is already saved.':'Use 3–30 lowercase letters, numbers or underscores, starting with a letter.'}}</small><label>Country · Required<CountrySelect v-model="form.country" required/></label></section>
<section v-else-if="step===1"><h2>{{form.kind==='Institute'?'About your institute':'About your teaching'}}</h2><p>These details are optional. You can update them later in My profile.</p><label>Subjects<input v-model="form.curriculum" maxlength="150" placeholder="For example: Mathematics, Science"></label><EducationLevelSelect v-model="form.grades"/><LanguageSelect v-model="form.languages"/><label>A short introduction · Optional<textarea v-model="form.bio" maxlength="1000" rows="3" placeholder="Tell learners a little about your teaching."/></label></section>
<section v-else><h2>Ready to save?</h2><p>Check your details before continuing.</p><dl><dt>Name</dt><dd>{{form.display_name}}</dd><dt>Username</dt><dd>@{{form.username}}</dd><dt>Country</dt><dd>{{form.country}}</dd><dt>Subjects</dt><dd>{{form.curriculum||'Not added'}}</dd><dt>Languages</dt><dd>{{form.languages||'Not added'}}</dd></dl><p>You can add photos, social links and more information later in My profile.</p><p v-if="!phoneVerified" role="alert">Please verify your mobile number before saving.</p></section>
<p v-if="error" role="alert" class="setup-error">{{error}} <button v-if="!phoneVerified" type="button" @click="load">Retry</button></p>
<footer><button v-if="step>0" type="button" class="secondary" :disabled="busy" @click="step--">Back</button><button class="primary" :disabled="busy||!valid||(step===2&&!phoneVerified)">{{busy?'Saving…':step===2?'Save your profile information':'Next →'}}</button></footer>
</form></template></section></template>
<style scoped>
.setup-profile{--student-border:#e7e1ee;--student-card:#fff;--student-ink:#241b32;--student-muted:#756b80;max-width:680px;margin:24px auto;padding:28px;background:white;border:1px solid #e7e1ee;border-radius:20px}.setup-steps{display:flex;list-style:none;gap:12px;padding:14px;margin:0 0 28px;background:#f8f5fc;border-radius:14px}.setup-steps li{display:flex;align-items:center;gap:7px;flex:1;font-size:12px;color:#81778c}.setup-steps span{display:grid;place-items:center;border:1px solid #ded5e9;border-radius:50%;width:25px;height:25px;flex-shrink:0}.setup-steps .current{color:#56288d;font-weight:700}.current span,.done span{background:#56288d;color:#fff}.setup-profile h2{font-size:24px;margin:0 0 12px}.setup-profile p{font-size:14px;line-height:1.7;color:#756b80;margin:12px 0 20px}.setup-profile label{display:flex;flex-direction:column;gap:8px;margin:18px 0;font-size:14px}.setup-profile input,.setup-profile textarea{box-sizing:border-box;width:100%;padding:14px;border:1px solid #e7e1ee;border-radius:12px;background:#fcfaff;color:#241b32;font:inherit}.setup-profile small{color:#756b80}.setup-profile footer{display:flex;justify-content:flex-end;gap:12px;margin-top:26px}.setup-profile button{padding:13px 22px;border-radius:24px;border:1px solid #e7e1ee;font:inherit;cursor:pointer}.primary{background:#56288d;color:white}.secondary{background:#f8f5fc;color:#56288d}.setup-profile button:disabled{opacity:.45;cursor:not-allowed}.setup-profile dl{display:grid;grid-template-columns:110px 1fr;gap:16px;padding:20px;background:#f8f5fc;border-radius:14px}.setup-profile dd{margin:0;overflow-wrap:anywhere}.setup-profile .setup-error{color:#a52642}.setup-profile :deep(.profile-language-results){max-height:160px}.setup-profile :deep(.profile-language-option){display:flex;flex-direction:row;align-items:center}.setup-profile :deep(input[type=checkbox]){width:18px;height:18px;flex-shrink:0}.setup-profile :deep(.profile-language-selected){display:flex;flex-wrap:wrap;gap:8px}@media(max-width:600px){.setup-profile{padding:18px}.setup-steps{gap:7px;padding:10px}.setup-steps li{flex-direction:column;text-align:center}.setup-profile footer button{flex:1}}
</style>
